/* ══════════════════════════
   HOOKS
══════════════════════════ */
function useFadeIn(delay = 0) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { setTimeout(() => el.classList.add("visible"), delay); obs.disconnect(); } },
      { threshold: 0.07 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [delay]);
  return ref;
}

/* ══════════════════════════
   HERO
══════════════════════════ */
function ServiceHero({ s }) {
  const cvs = useRef(null);
  useEffect(() => {
    const c = cvs.current; if (!c) return;
    const ctx = c.getContext("2d");
    let W, H, pts = [], rafId;
    const resize = () => { W = c.width = c.offsetWidth; H = c.height = c.offsetHeight; };
    const mkPt = () => ({ x: Math.random()*W, y: Math.random()*H, vx:(Math.random()-.5)*.3, vy:(Math.random()-.5)*.3, r:Math.random()*2+.5 });
    resize(); pts = Array.from({length:50}, mkPt);
    const colMap = { orange:"rgba(255,77,0,.3)", blue:"rgba(59,130,246,.3)", teal:"rgba(20,184,166,.3)" };
    const col = colMap[s.color] || colMap.orange;
    const draw = () => {
      ctx.clearRect(0,0,W,H);
      pts.forEach(p => {
        p.x+=p.vx; p.y+=p.vy;
        if(p.x<0||p.x>W) p.vx*=-1;
        if(p.y<0||p.y>H) p.vy*=-1;
        ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
        ctx.fillStyle=col; ctx.fill();
      });
      pts.forEach((a,i) => pts.slice(i+1).forEach(b => {
        const d = Math.hypot(a.x-b.x, a.y-b.y);
        if(d<110){ ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y); ctx.strokeStyle=`rgba(255,77,0,${(1-d/110)*.07})`; ctx.stroke(); }
      }));
      rafId = requestAnimationFrame(draw);
    };
    draw();
    window.addEventListener("resize", resize);
    return () => { cancelAnimationFrame(rafId); window.removeEventListener("resize", resize); };
  }, [s.color]);

  const words = s.title.split(" ");
  const w1 = words.slice(0,2).join(" ");
  const w2 = words.slice(2).join(" ");

  return (
    <section className={`sp-hero sp-hero--${s.color}`}>
      <canvas className="sp-hero-canvas" ref={cvs} />
      <div className="sp-mesh">{[...Array(4)].map((_,i)=><div key={`h${i}`} className="sp-mh" style={{top:`${20+i*20}%`,animationDelay:`${i*.8}s`}}/>)}{[...Array(4)].map((_,i)=><div key={`v${i}`} className="sp-mv" style={{left:`${20+i*20}%`,animationDelay:`${i*.8}s`}}/>)}</div>
      <div className={`sp-glow1 sp-g1--${s.color}`}/><div className="sp-glow2"/>
      <div className="sp-noise"/>
      <div className="sp-hero-inner">
        <div className={`sp-chip sp-chip--${s.color}`}><i className={s.icon}/>{s.category}</div>
        <h1 className="sp-h1"><span className="sp-w1">{w1}</span>{w2&&<span className={`sp-w2 sp-grad--${s.color}`}>{w2}</span>}</h1>
        <p className="sp-tagline">{s.tagline}</p>
        <p className="sp-hdesc">{s.description}</p>
        <div className="sp-hbtns">
          <a href="/contact" className={`sp-btn sp-fill--${s.color} sp-magnetic`}>{s.cta}<i className="bx bx-right-arrow-alt"/></a>
          <a href="/contact" className="sp-btn sp-ghost">Contact Us<i className="bx bx-chevron-right"/></a>
        </div>
      </div>
    </section>
  );
}

